toolScript:
let targetCMYK = { c: 0, m: 0, y: 0, k: 0 };
let currentStreak = 0;
let isRevealed = false;

function cmykToRgb(c, m, y, k) {
    const C = c / 100;
    const M = m / 100;
    const Y = y / 100;
    const K = k / 100;
    const r = 255 * (1 - C) * (1 - K);
    const g = 255 * (1 - M) * (1 - K);
    const b = 255 * (1 - Y) * (1 - K);
    return { r: Math.round(r), g: Math.round(g), b: Math.round(b) };
}

function rgbToHex(r, g, b) {
    return '#' + ((1 << 24) + (r << 16) + (g << 8) + b).toString(16).slice(1).toUpperCase();
}

function generateTarget() {
    targetCMYK = {
        c: Math.floor(Math.random() * 90) + 5,
        m: Math.floor(Math.random() * 90) + 5,
        y: Math.floor(Math.random() * 90) + 5,
        k: Math.floor(Math.random() * 45)
    };
    const rgb = cmykToRgb(targetCMYK.c, targetCMYK.m, targetCMYK.y, targetCMYK.k);
    const swatch = document.getElementById('target-swatch');
    if (swatch) {
        swatch.style.backgroundColor = `rgb(${rgb.r}, ${rgb.g}, ${rgb.b})`;
        swatch.dataset.rgb = `rgb(${rgb.r}, ${rgb.g}, ${rgb.b})`;
        swatch.dataset.hex = rgbToHex(rgb.r, rgb.g, rgb.b);
    }
    const hexEl = document.getElementById('target-hex');
    if (hexEl) hexEl.innerText = '???';
    const rgbText = document.getElementById('target-rgb-text');
    if (rgbText) rgbText.innerText = 'Target locked';
}

function updateMix() {
    if (isRevealed) return;
    const sliderC = document.getElementById('slider-c');
    const sliderM = document.getElementById('slider-m');
    const sliderY = document.getElementById('slider-y');
    const sliderK = document.getElementById('slider-k');
    const c = sliderC ? parseInt(sliderC.value, 10) : 0;
    const m = sliderM ? parseInt(sliderM.value, 10) : 0;
    const y = sliderY ? parseInt(sliderY.value, 10) : 0;
    const k = sliderK ? parseInt(sliderK.value, 10) : 0;

    const valC = document.getElementById('val-c');
    const valM = document.getElementById('val-m');
    const valY = document.getElementById('val-y');
    const valK = document.getElementById('val-k');
    if (valC) valC.innerText = c + '%';
    if (valM) valM.innerText = m + '%';
    if (valY) valY.innerText = y + '%';
    if (valK) valK.innerText = k + '%';

    const rgb = cmykToRgb(c, m, y, k);
    const userSwatch = document.getElementById('user-swatch');
    if (userSwatch) {
        userSwatch.style.backgroundColor = `rgb(${rgb.r}, ${rgb.g}, ${rgb.b})`;
    }
    const userHex = document.getElementById('user-hex');
    if (userHex) {
        userHex.innerText = rgbToHex(rgb.r, rgb.g, rgb.b);
    }
}

function submitGuess() {
    if (isRevealed) return;
    isRevealed = true;
    const c = parseInt(document.getElementById('slider-c')?.value || '0', 10);
    const m = parseInt(document.getElementById('slider-m')?.value || '0', 10);
    const y = parseInt(document.getElementById('slider-y')?.value || '0', 10);
    const k = parseInt(document.getElementById('slider-k')?.value || '0', 10);

    const diffC = Math.abs(targetCMYK.c - c);
    const diffM = Math.abs(targetCMYK.m - m);
    const diffY = Math.abs(targetCMYK.y - y);
    const diffK = Math.abs(targetCMYK.k - k);

    const totalDiff = (diffC + diffM + diffY + (diffK * 1.5)) / 4.5;
    let accuracy = Math.max(0, 100 - totalDiff);
    accuracy = Math.min(100, Math.round(accuracy * 1.08));

    const scoreEl = document.getElementById('result-score');
    if (scoreEl) scoreEl.innerText = accuracy + '%';

    let message = '';
    if (accuracy >= 95) {
        message = 'Near-perfect match. Master level precision.';
        currentStreak++;
    } else if (accuracy >= 85) {
        message = 'Strong ink calibration. Very close.';
        currentStreak++;
    } else if (accuracy >= 70) {
        message = 'Decent match. Check your Key (K) channel.';
        currentStreak = 0;
    } else {
        message = 'Needs re-balancing. Adjust Key and Cyan.';
        currentStreak = 0;
    }

    const streakEl = document.getElementById('streak-display');
    if (streakEl) streakEl.innerText = currentStreak;

    const feedbackEl = document.getElementById('feedback-text');
    if (feedbackEl) feedbackEl.innerText = message;

    const targetSwatch = document.getElementById('target-swatch');
    if (targetSwatch) {
        const hexEl = document.getElementById('target-hex');
        if (hexEl && targetSwatch.dataset.hex) hexEl.innerText = targetSwatch.dataset.hex;
        const rgbText = document.getElementById('target-rgb-text');
        if (rgbText && targetSwatch.dataset.rgb) rgbText.innerText = targetSwatch.dataset.rgb;
    }

    const overlay = document.getElementById('result-overlay');
    if (overlay) {
        overlay.classList.remove('opacity-0', 'pointer-events-none');
        overlay.classList.add('opacity-100', 'pointer-events-auto');
    }

    const btnSubmit = document.getElementById('btn-submit');
    const btnNext = document.getElementById('btn-next');
    if (btnSubmit) btnSubmit.classList.add('hidden');
    if (btnNext) btnNext.classList.remove('hidden');
}

function nextRound() {
    isRevealed = false;
    const overlay = document.getElementById('result-overlay');
    if (overlay) {
        overlay.classList.add('opacity-0', 'pointer-events-none');
        overlay.classList.remove('opacity-100', 'pointer-events-auto');
    }

    const btnSubmit = document.getElementById('btn-submit');
    const btnNext = document.getElementById('btn-next');
    if (btnSubmit) btnSubmit.classList.remove('hidden');
    if (btnNext) btnNext.classList.add('hidden');

    ['slider-c', 'slider-m', 'slider-y', 'slider-k'].forEach(id => {
        const el = document.getElementById(id);
        if (el) el.value = '0';
    });
    updateMix();
    setTimeout(generateTarget, 200);
}

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => { generateTarget(); updateMix(); });
} else {
    generateTarget();
    updateMix();
}

window.updateMix = updateMix;
window.submitGuess = submitGuess;
window.nextRound = nextRound;
